{
  "name": "SME Sales Strategy Advisor",
  "description": "An intelligent AI-powered sales performance advisory system that analyzes ERP exports to provide actionable business strategies via voice and visual dashboards.",
  "requestFramePermissions": [
    "microphone"
  ]
}

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export interface SalesRecord {
  date: string;
  invoiceNo: string;
  customerName: string;
  distributor: string;
  product: string;
  quantity: number;
  revenue: number;
  discount: number;
  cost: number;
  creditDays: number;
  outstandingAmount: number;
  region: string;
  salesRep: string;
}

export enum RiskLevel {
  LOW = 'Low',
  MEDIUM = 'Medium',
  HIGH = 'High'
}

export interface AdvisoryOutput {
  keyInsight: string;
  rootCause: string;
  riskLevel: RiskLevel;
  recommendedAction: string;
  expectedImpact: string;
}

export interface DashboardStats {
  totalRevenue: number;
  totalProfit: number;
  avgDiscount: number;
  totalOutstanding: number;
  topProducts: { name: string; revenue: number }[];
  regionalPerformance: { region: string; revenue: number }[];
}

export enum Language {
  ENGLISH = 'English',
  SPANISH = 'Spanish',
  FRENCH = 'French',
  GERMAN = 'German',
  CHINESE = 'Chinese',
  HINDI = 'Hindi'
}

import { GoogleGenAI, Type, Modality } from "@google/genai";
import { SalesRecord, AdvisoryOutput, RiskLevel } from "../types";

const API_KEY = process.env.API_KEY || "";

export const getGeminiAdvisor = () => {
  const ai = new GoogleGenAI({ apiKey: API_KEY });
  return ai;
};

export const analyzeSalesData = async (data: SalesRecord[], prompt: string): Promise<AdvisoryOutput[]> => {
  const ai = getGeminiAdvisor();

  // Create a summary of the data to keep the context window manageable while remaining accurate
  const summary = data.slice(0, 100).map(r => ({
    r: r.revenue,
    p: r.product,
    c: r.customerName,
    d: r.discount,
    reg: r.region,
    o: r.outstandingAmount
  }));

  const response = await ai.models.generateContent({
    model: "gemini-3-pro-preview",
    contents: `
      Analyze this SME sales data summary: ${JSON.stringify(summary)}.
      Task: ${prompt}
      Provide actionable business recommendations in a structured JSON format.
    `,
    config: {
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.ARRAY,
        items: {
          type: Type.OBJECT,
          properties: {
            keyInsight: { type: Type.STRING },
            rootCause: { type: Type.STRING },
            riskLevel: { type: Type.STRING, enum: ["Low", "Medium", "High"] },
            recommendedAction: { type: Type.STRING },
            expectedImpact: { type: Type.STRING }
          },
          required: ["keyInsight", "rootCause", "riskLevel", "recommendedAction", "expectedImpact"]
        }
      }
    }
  });

  try {
    return JSON.parse(response.text || "[]");
  } catch (e) {
    console.error("Failed to parse AI response", e);
    return [];
  }
};

export const getVoiceSession = async (
  language: string,
  dataContext: string,
  callbacks: any
) => {
  const ai = getGeminiAdvisor();
  return ai.live.connect({
    model: 'gemini-2.5-flash-native-audio-preview-12-2025',
    callbacks,
    config: {
      responseModalities: [Modality.AUDIO],
      speechConfig: {
        voiceConfig: { prebuiltVoiceConfig: { voiceName: 'Kore' } },
      },
      systemInstruction: `
        You are an expert Sales Strategy Advisor for an SME. 
        You have analyzed the following sales data context: ${dataContext}.
        Speak in a professional, decision-focused, and advisory tone.
        The user has selected ${language} as their preferred language. Communicate exclusively in ${language}.
        When asked "Why are my sales declining?", analyze trends, region, SKU mix, and distributor behavior.
        When asked for next month's plan, provide a prioritized, measurable action plan.
        Always focus on measurable impact.
      `,
    },
  });
};

