import React, { useMemo, useState, useEffect } from 'react';
import { SalesRecord, AdvisoryOutput, RiskLevel } from '../types';
import { 
  BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, 
  LineChart, Line, AreaChart, Area, Cell, PieChart, Pie
} from 'recharts';
import { analyzeSalesData } from '../services/gemini';
import { AlertCircle, TrendingUp, DollarSign, Users, Target, ShieldAlert, Zap, Loader2 } from 'lucide-react';

interface DashboardProps {
  data: SalesRecord[];
}

const Dashboard: React.FC<DashboardProps> = ({ data }) => {
  const [advisory, setAdvisory] = useState<AdvisoryOutput[]>([]);
  const [loading, setLoading] = useState(false);

  const stats = useMemo(() => {
    const revenue = data.reduce((acc, curr) => acc + curr.revenue, 0);
    const profit = data.reduce((acc, curr) => acc + (curr.revenue - curr.cost - curr.discount), 0);
    const outstanding = data.reduce((acc, curr) => acc + curr.outstandingAmount, 0);
    const discountRate = (data.reduce((acc, curr) => acc + curr.discount, 0) / revenue) * 100;

    const products = data.reduce((acc: any, curr) => {
      acc[curr.product] = (acc[curr.product] || 0) + curr.revenue;
      return acc;
    }, {});

    const trend = data.slice(0, 12).map((r, i) => ({
      name: r.date,
      revenue: r.revenue,
      target: r.revenue * 1.1,
    }));

    return {
      revenue,
      profit,
      outstanding,
      discountRate,
      topProducts: Object.entries(products).map(([name, value]) => ({ name, value })).sort((a: any, b: any) => b.value - a.value).slice(0, 5),
      trend
    };
  }, [data]);

  useEffect(() => {
    const fetchAdvisory = async () => {
      setLoading(true);
      const prompt = `Analyze: Monthly sales trend, product contribution, distributor performance, and credit outstanding. 
                      Format: Key Insight, Root Cause, Business Risk Level (Low/Medium/High), Recommended Action, Expected Impact.`;
      const result = await analyzeSalesData(data, prompt);
      setAdvisory(result);
      setLoading(false);
    };
    fetchAdvisory();
  }, [data]);

  const COLORS = ['#6366f1', '#818cf8', '#a5b4fc', '#c7d2fe', '#e0e7ff'];

  return (
    <div className="space-y-8 pb-20">
      {/* Top Stats */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
        <StatCard title="Total Revenue" value={`$${stats.revenue.toLocaleString()}`} icon={<TrendingUp className="w-5 h-5" />} color="text-emerald-600" bg="bg-emerald-50" />
        <StatCard title="Net Profit" value={`$${stats.profit.toLocaleString()}`} icon={<DollarSign className="w-5 h-5" />} color="text-indigo-600" bg="bg-indigo-50" />
        <StatCard title="Total Outstanding" value={`$${stats.outstanding.toLocaleString()}`} icon={<ShieldAlert className="w-5 h-5" />} color="text-rose-600" bg="bg-rose-50" />
        <StatCard title="Avg Discount" value={`${stats.discountRate.toFixed(1)}%`} icon={<Zap className="w-5 h-5" />} color="text-amber-600" bg="bg-amber-50" />
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
        {/* Main Chart */}
        <div className="lg:col-span-2 bg-white p-6 rounded-2xl shadow-sm border border-slate-100">
          <div className="flex items-center justify-between mb-6">
            <h3 className="font-bold text-slate-800">Sales Trend vs Targets</h3>
            <span className="text-xs font-medium text-slate-400 bg-slate-50 px-2 py-1 rounded">Monthly View</span>
          </div>
          <div className="h-80">
            <ResponsiveContainer width="100%" height="100%">
              <AreaChart data={stats.trend}>
                <defs>
                  <linearGradient id="colorRev" x1="0" y1="0" x2="0" y2="1">
                    <stop offset="5%" stopColor="#6366f1" stopOpacity={0.1}/>
                    <stop offset="95%" stopColor="#6366f1" stopOpacity={0}/>
                  </linearGradient>
                </defs>
                <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" />
                <XAxis dataKey="name" axisLine={false} tickLine={false} tick={{fontSize: 12, fill: '#94a3b8'}} />
                <YAxis axisLine={false} tickLine={false} tick={{fontSize: 12, fill: '#94a3b8'}} />
                <Tooltip 
                  contentStyle={{ borderRadius: '12px', border: 'none', boxShadow: '0 4px 6px -1px rgb(0 0 0 / 0.1)' }}
                />
                <Area type="monotone" dataKey="revenue" stroke="#6366f1" fillOpacity={1} fill="url(#colorRev)" strokeWidth={3} />
                <Line type="monotone" dataKey="target" stroke="#cbd5e1" strokeDasharray="5 5" />
              </AreaChart>
            </ResponsiveContainer>
          </div>
        </div>

        {/* Product Mix */}
        <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-100">
          <h3 className="font-bold text-slate-800 mb-6">Product Revenue Contribution</h3>
          <div className="h-64">
            <ResponsiveContainer width="100%" height="100%">
              <PieChart>
                <Pie
                  data={stats.topProducts}
                  innerRadius={60}
                  outerRadius={80}
                  paddingAngle={5}
                  dataKey="value"
                >
                  {stats.topProducts.map((entry, index) => (
                    <Cell key={`cell-${index}`} fill={COLORS[index % COLORS.length]} />
                  ))}
                </Pie>
                <Tooltip />
              </PieChart>
            </ResponsiveContainer>
          </div>
          <div className="mt-4 space-y-2">
            {stats.topProducts.map((p, i) => (
              <div key={p.name} className="flex items-center justify-between text-sm">
                <div className="flex items-center gap-2">
                  <div className="w-2 h-2 rounded-full" style={{backgroundColor: COLORS[i]}} />
                  <span className="text-slate-600 truncate max-w-[120px]">{p.name}</span>
                </div>
                <span className="font-semibold text-slate-800">${p.value.toLocaleString()}</span>
              </div>
            ))}
          </div>
        </div>
      </div>

      {/* AI Advisory Section */}
      <div className="space-y-6">
        <div className="flex items-center gap-2">
          <Zap className="w-5 h-5 text-indigo-500" />
          <h3 className="text-xl font-bold text-slate-800">AI Strategic Advisory</h3>
          {loading && <Loader2 className="w-4 h-4 animate-spin text-slate-400" />}
        </div>

        <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-6">
          {advisory.length > 0 ? advisory.map((item, idx) => (
            <AdvisoryCard key={idx} item={item} />
          )) : (
            Array.from({length: 3}).map((_, i) => (
              <div key={i} className="h-64 rounded-2xl bg-slate-100 animate-pulse" />
            ))
          )}
        </div>
      </div>
    </div>
  );
};

const StatCard = ({ title, value, icon, color, bg }: any) => (
  <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-100 flex items-start gap-4">
    <div className={`p-3 rounded-xl ${bg} ${color}`}>
      {icon}
    </div>
    <div>
      <p className="text-sm font-medium text-slate-400">{title}</p>
      <h4 className="text-2xl font-bold text-slate-800 mt-1">{value}</h4>
    </div>
  </div>
);

const AdvisoryCard = ({ item }: { item: AdvisoryOutput }) => {
  const riskColors = {
    [RiskLevel.LOW]: 'bg-emerald-50 text-emerald-700 border-emerald-100',
    [RiskLevel.MEDIUM]: 'bg-amber-50 text-amber-700 border-amber-100',
    [RiskLevel.HIGH]: 'bg-rose-50 text-rose-700 border-rose-100',
  };

  return (
    <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-100 flex flex-col h-full hover:shadow-md transition-shadow">
      <div className="flex justify-between items-start mb-4">
        <span className={`px-2 py-0.5 rounded-full text-xs font-bold border uppercase tracking-wide ${riskColors[item.riskLevel]}`}>
          {item.riskLevel} Risk
        </span>
      </div>
      <h4 className="font-bold text-slate-800 text-lg mb-2 leading-tight">{item.keyInsight}</h4>
      <div className="mb-4">
        <p className="text-xs font-semibold text-slate-400 uppercase tracking-tighter mb-1">Root Cause</p>
        <p className="text-sm text-slate-600">{item.rootCause}</p>
      </div>
      <div className="mt-auto pt-4 border-t border-slate-50 space-y-3">
        <div className="flex items-start gap-3">
          <div className="p-1.5 rounded-lg bg-indigo-50 text-indigo-600 shrink-0">
            <Target className="w-3.5 h-3.5" />
          </div>
          <div>
            <p className="text-xs font-bold text-slate-800">Recommendation</p>
            <p className="text-xs text-slate-500">{item.recommendedAction}</p>
          </div>
        </div>
        <div className="flex items-start gap-3">
          <div className="p-1.5 rounded-lg bg-emerald-50 text-emerald-600 shrink-0">
            <TrendingUp className="w-3.5 h-3.5" />
          </div>
          <div>
            <p className="text-xs font-bold text-slate-800">Expected Impact</p>
            <p className="text-xs text-slate-500">{item.expectedImpact}</p>
          </div>
        </div>
      </div>
    </div>
  );
};

export default Dashboard;

import React, { useState, useRef, useEffect, useCallback } from 'react';
import { getVoiceSession } from '../services/gemini';
import { Mic, MicOff, Volume2, VolumeX, X, MessageCircle, BarChart2 } from 'lucide-react';
import { LiveServerMessage, Blob } from '@google/genai';

interface VoiceAssistantProps {
  language: string;
  dataContext: string;
}

const VoiceAssistant: React.FC<VoiceAssistantProps> = ({ language, dataContext }) => {
  const [isActive, setIsActive] = useState(false);
  const [isMinimized, setIsMinimized] = useState(true);
  const [transcript, setTranscript] = useState<string[]>([]);
  const [currentThought, setCurrentThought] = useState("");

  const inputAudioContext = useRef<AudioContext | null>(null);
  const outputAudioContext = useRef<AudioContext | null>(null);
  const sources = useRef<Set<AudioBufferSourceNode>>(new Set());
  const nextStartTime = useRef(0);
  const sessionPromise = useRef<any>(null);

  const decode = (base64: string) => {
    const binaryString = atob(base64);
    const bytes = new Uint8Array(binaryString.length);
    for (let i = 0; i < binaryString.length; i++) bytes[i] = binaryString.charCodeAt(i);
    return bytes;
  };

  const encode = (bytes: Uint8Array) => {
    let binary = '';
    for (let i = 0; i < bytes.byteLength; i++) binary += String.fromCharCode(bytes[i]);
    return btoa(binary);
  };

  const decodeAudioData = async (data: Uint8Array, ctx: AudioContext, sampleRate: number, numChannels: number) => {
    const dataInt16 = new Int16Array(data.buffer);
    const frameCount = dataInt16.length / numChannels;
    const buffer = ctx.createBuffer(numChannels, frameCount, sampleRate);
    for (let channel = 0; channel < numChannels; channel++) {
      const channelData = buffer.getChannelData(channel);
      for (let i = 0; i < frameCount; i++) channelData[i] = dataInt16[i * numChannels + channel] / 32768.0;
    }
    return buffer;
  };

  const createBlob = (data: Float32Array): Blob => {
    const int16 = new Int16Array(data.length);
    for (let i = 0; i < data.length; i++) int16[i] = data[i] * 32768;
    return {
      data: encode(new Uint8Array(int16.buffer)),
      mimeType: 'audio/pcm;rate=16000',
    };
  };

  const stopSession = useCallback(() => {
    setIsActive(false);
    if (inputAudioContext.current) inputAudioContext.current.close();
    if (outputAudioContext.current) outputAudioContext.current.close();
    sources.current.forEach(s => s.stop());
    sources.current.clear();
  }, []);

  const startSession = async () => {
    try {
      const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
      inputAudioContext.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 16000 });
      outputAudioContext.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });

      const outputNode = outputAudioContext.current.createGain();
      outputNode.connect(outputAudioContext.current.destination);

      sessionPromise.current = getVoiceSession(language, dataContext, {
        onopen: () => {
          setIsActive(true);
          const source = inputAudioContext.current!.createMediaStreamSource(stream);
          const scriptProcessor = inputAudioContext.current!.createScriptProcessor(4096, 1, 1);
          scriptProcessor.onaudioprocess = (e) => {
            const inputData = e.inputBuffer.getChannelData(0);
            const pcmBlob = createBlob(inputData);
            sessionPromise.current?.then((session: any) => session.sendRealtimeInput({ media: pcmBlob }));
          };
          source.connect(scriptProcessor);
          scriptProcessor.connect(inputAudioContext.current!.destination);
        },
        onmessage: async (message: LiveServerMessage) => {
          if (message.serverContent?.outputTranscription) {
            const text = message.serverContent.outputTranscription.text;
            setCurrentThought(prev => prev + text);
          }

          if (message.serverContent?.turnComplete) {
            setTranscript(prev => [...prev.slice(-4), currentThought]);
            setCurrentThought("");
          }

          const base64Audio = message.serverContent?.modelTurn?.parts[0]?.inlineData?.data;
          if (base64Audio && outputAudioContext.current) {
            nextStartTime.current = Math.max(nextStartTime.current, outputAudioContext.current.currentTime);
            const buffer = await decodeAudioData(decode(base64Audio), outputAudioContext.current, 24000, 1);
            const source = outputAudioContext.current.createBufferSource();
            source.buffer = buffer;
            source.connect(outputNode);
            source.addEventListener('ended', () => sources.current.delete(source));
            source.start(nextStartTime.current);
            nextStartTime.current += buffer.duration;
            sources.current.add(source);
          }

          if (message.serverContent?.interrupted) {
            sources.current.forEach(s => s.stop());
            sources.current.clear();
            nextStartTime.current = 0;
          }
        },
        onerror: () => stopSession(),
        onclose: () => stopSession(),
      });
    } catch (err) {
      console.error("Voice init failed", err);
    }
  };

  const toggleAssistant = () => {
    if (isActive) {
      stopSession();
    } else {
      setIsMinimized(false);
      startSession();
    }
  };

  return (
    <>
      {/* Floating Button */}
      <button 
        onClick={toggleAssistant}
