                {currentThought}...
              </div>
            )}
          </div>

          <div className="p-4 bg-white border-t border-slate-100">
            <div className="flex items-center justify-between">
              <div className="flex gap-1">
                {[...Array(5)].map((_, i) => (
                  <div 
                    key={i} 
                    className={`w-1 bg-indigo-200 rounded-full transition-all duration-300 ${isActive ? 'animate-bounce' : 'h-1'}`}
                    style={{ height: isActive ? `${Math.random() * 20 + 5}px` : '4px', animationDelay: `${i * 0.1}s` }}
                  />
                ))}
              </div>
              <span className="text-[10px] font-bold text-indigo-600 uppercase tracking-widest">{isActive ? 'Listening' : 'Standby'}</span>
            </div>
          </div>
        </div>
      )}
    </>
  );
};

