import { GoogleGenAI, Type, Modality } from "@google/genai";
import { SalesRecord, AdvisoryOutput, RiskLevel, Language } from "../types";

/**
 * Analyzes sales data using Gemini 3 Pro for complex reasoning and JSON output.
 * Now supports generating content in the user's preferred language.
 */
export const analyzeSalesData = async (data: SalesRecord[], prompt: string, language: Language): Promise<AdvisoryOutput[]> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  // Create a summary of the data
  const summary = data.slice(0, 100).map(r => ({
    r: r.revenue,
    p: r.product,
    c: r.customerName,
    d: r.discount,
    reg: r.region,
    o: r.outstandingAmount
  }));

  const response = await ai.models.generateContent({
    model: "gemini-3-pro-preview",
    contents: `
      Analyze this SME sales data summary: ${JSON.stringify(summary)}.
      Task: ${prompt}

      CRITICAL REQUIREMENT: 
      The user's preferred language is ${language}. 
      All text values in the JSON output (keyInsight, rootCause, recommendedAction, expectedImpact) MUST be written in ${language}.

      Maintain a professional business advisory tone appropriate for that culture.
    `,
    config: {
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.ARRAY,
        items: {
          type: Type.OBJECT,
          properties: {
            keyInsight: { type: Type.STRING },
            rootCause: { type: Type.STRING },
            riskLevel: { type: Type.STRING, enum: ["Low", "Medium", "High"] },
            recommendedAction: { type: Type.STRING },
            expectedImpact: { type: Type.STRING }
          },
          required: ["keyInsight", "rootCause", "riskLevel", "recommendedAction", "expectedImpact"]
        }
      }
    }
  });

  try {
    const text = response.text?.trim() || "[]";
    return JSON.parse(text);
  } catch (e) {
    console.error("Failed to parse AI response", e);
    return [];
  }
};

/**
 * Connects to the Live API for real-time voice advisory.
 */
export const getVoiceSession = async (
  language: string,
  dataContext: string,
  callbacks: any
) => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
  return ai.live.connect({
    model: 'gemini-2.5-flash-native-audio-preview-12-2025',
    callbacks,
    config: {
      responseModalities: [Modality.AUDIO],
      speechConfig: {
        voiceConfig: { prebuiltVoiceConfig: { voiceName: 'Kore' } },
      },
      systemInstruction: `
        You are an expert Sales Strategy Advisor for an SME. 
        You have analyzed the following sales data context: ${dataContext}.
        Speak in a professional, decision-focused, and advisory tone.
        The user has selected ${language} as their preferred language. Communicate exclusively in ${language}.
        When asked "Why are my sales declining?", analyze trends, region, SKU mix, and distributor behavior.
        When asked for next month's plan, provide a prioritized, measurable action plan.
        Always focus on measurable impact.
      `,
    },
  });
};

