const Dashboard: React.FC<DashboardProps> = ({ data, language }) => {
  const [advisory, setAdvisory] = useState<AdvisoryOutput[]>([]);
  const [loading, setLoading] = useState(false);

  const t = UI_TRANSLATIONS[language] || UI_TRANSLATIONS[Language.ENGLISH];
  const isRtl = language === Language.ARABIC || language === Language.URDU;

  const stats = useMemo(() => {
    const revenue = data.reduce((acc, curr) => acc + curr.revenue, 0);
    const profit = data.reduce((acc, curr) => acc + (curr.revenue - curr.cost - curr.discount), 0);
    const outstanding = data.reduce((acc, curr) => acc + curr.outstandingAmount, 0);
    const discountRate = (data.reduce((acc, curr) => acc + curr.discount, 0) / (revenue || 1)) * 100;

    const products = data.reduce((acc: any, curr) => {
      acc[curr.product] = (acc[curr.product] || 0) + curr.revenue;
      return acc;
    }, {});

    const trend = data.slice(0, 12).map((r) => ({
      name: r.date,
      revenue: r.revenue,
      target: r.revenue * 1.1,
    }));

    return {
      revenue,
      profit,
      outstanding,
      discountRate,
      topProducts: Object.entries(products).map(([name, value]) => ({ name, value: value as number })).sort((a, b) => b.value - a.value).slice(0, 5),
      trend
    };
  }, [data]);

  useEffect(() => {
    const fetchAdvisory = async () => {
      if (data.length === 0) return;
      setLoading(true);
      const prompt = `Analyze: Monthly sales trend, product contribution, distributor performance, and credit outstanding. 
                      Format: Key Insight, Root Cause, Business Risk Level (Low/Medium/High), Recommended Action, Expected Impact.`;
      const result = await analyzeSalesData(data, prompt, language);
      setAdvisory(result);
      setLoading(false);
    };
    fetchAdvisory();
  }, [data, language]);

  const COLORS = ['#6366f1', '#818cf8', '#a5b4fc', '#c7d2fe', '#e0e7ff'];

  return (
    <div className={`space-y-8 pb-20 ${isRtl ? 'text-right' : 'text-left'}`} dir={isRtl ? 'rtl' : 'ltr'}>
      {/* Top Stats */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
        <StatCard title={t.revenue} value={`$${stats.revenue.toLocaleString()}`} icon={<TrendingUp className="w-5 h-5" />} color="text-emerald-600" bg="bg-emerald-50" />
        <StatCard title={t.profit} value={`$${stats.profit.toLocaleString()}`} icon={<DollarSign className="w-5 h-5" />} color="text-indigo-600" bg="bg-indigo-50" />
        <StatCard title={t.outstanding} value={`$${stats.outstanding.toLocaleString()}`} icon={<ShieldAlert className="w-5 h-5" />} color="text-rose-600" bg="bg-rose-50" />
        <StatCard title={t.discount} value={`${stats.discountRate.toFixed(1)}%`} icon={<Zap className="w-5 h-5" />} color="text-amber-600" bg="bg-amber-50" />
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
        <div className="lg:col-span-2 bg-white p-6 rounded-2xl shadow-sm border border-slate-100">
          <div className={`flex items-center justify-between mb-6 ${isRtl ? 'flex-row-reverse' : ''}`}>
            <h3 className="font-bold text-slate-800">{t.trendTitle}</h3>
            <span className="text-xs font-medium text-slate-400 bg-slate-50 px-2 py-1 rounded">{t.monthlyView}</span>
          </div>
          <div className="h-80">
            <ResponsiveContainer width="100%" height="100%">
              <AreaChart data={stats.trend}>
                <defs>
                  <linearGradient id="colorRev" x1="0" y1="0" x2="0" y2="1">
                    <stop offset="5%" stopColor="#6366f1" stopOpacity={0.1}/>
                    <stop offset="95%" stopColor="#6366f1" stopOpacity={0}/>
                  </linearGradient>
                </defs>
                <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" />
                <XAxis dataKey="name" axisLine={false} tickLine={false} tick={{fontSize: 10, fill: '#94a3b8'}} reversed={isRtl} />
                <YAxis axisLine={false} tickLine={false} tick={{fontSize: 10, fill: '#94a3b8'}} orientation={isRtl ? 'right' : 'left'} />
                <Tooltip 
                  contentStyle={{ borderRadius: '12px', border: 'none', boxShadow: '0 4px 6px -1px rgb(0 0 0 / 0.1)' }}
                />
                <Area type="monotone" dataKey="revenue" stroke="#6366f1" fillOpacity={1} fill="url(#colorRev)" strokeWidth={3} />
                <Line type="monotone" dataKey="target" stroke="#cbd5e1" strokeDasharray="5 5" />
              </AreaChart>
            </ResponsiveContainer>
          </div>
        </div>

        <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-100">
          <h3 className="font-bold text-slate-800 mb-6">{t.mixTitle}</h3>
