    let binary = '';
    const len = bytes.byteLength;
    for (let i = 0; i < len; i++) {
      binary += String.fromCharCode(bytes[i]);
    }
    return btoa(binary);
  };

  // Manual audio decoding as per guidelines (the model returns raw PCM bytes)
  const decodeAudioData = async (
    data: Uint8Array,
    ctx: AudioContext,
    sampleRate: number,
    numChannels: number,
  ): Promise<AudioBuffer> => {
    const dataInt16 = new Int16Array(data.buffer);
    const frameCount = dataInt16.length / numChannels;
    const buffer = ctx.createBuffer(numChannels, frameCount, sampleRate);

    for (let channel = 0; channel < numChannels; channel++) {
      const channelData = buffer.getChannelData(channel);
      for (let i = 0; i < frameCount; i++) {
        channelData[i] = dataInt16[i * numChannels + channel] / 32768.0;
      }
    }
    return buffer;
  };

  // Create PCM blob for streaming to Gemini
  const createBlob = (data: Float32Array): Blob => {
    const l = data.length;
    const int16 = new Int16Array(l);
    for (let i = 0; i < l; i++) {
      int16[i] = data[i] * 32768;
    }
    return {
      data: encode(new Uint8Array(int16.buffer)),
      mimeType: 'audio/pcm;rate=16000',
    };
  };

  const stopSession = useCallback(() => {
    setIsActive(false);
    if (inputAudioContext.current) inputAudioContext.current.close();
    if (outputAudioContext.current) outputAudioContext.current.close();
    sources.current.forEach(s => {
      try { s.stop(); } catch (e) {}
    });
    sources.current.clear();
  }, []);

  const startSession = async () => {
    try {
      const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
      inputAudioContext.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 16000 });
      outputAudioContext.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });

      const outputNode = outputAudioContext.current.createGain();
      outputNode.connect(outputAudioContext.current.destination);

      sessionPromise.current = getVoiceSession(language, dataContext, {
        onopen: () => {
          setIsActive(true);
          const source = inputAudioContext.current!.createMediaStreamSource(stream);
          const scriptProcessor = inputAudioContext.current!.createScriptProcessor(4096, 1, 1);
          scriptProcessor.onaudioprocess = (e) => {
            const inputData = e.inputBuffer.getChannelData(0);
            const pcmBlob = createBlob(inputData);
            sessionPromise.current?.then((session) => {
              session.sendRealtimeInput({ media: pcmBlob });
            });
          };
          source.connect(scriptProcessor);
          scriptProcessor.connect(inputAudioContext.current!.destination);
        },
        onmessage: async (message: LiveServerMessage) => {
          if (message.serverContent?.outputTranscription) {
            const text = message.serverContent.outputTranscription.text;
            setCurrentThought(prev => prev + text);
          }

          if (message.serverContent?.turnComplete) {
            setCurrentThought(thought => {
              setTranscript(prev => [...prev.slice(-4), thought]);
              return "";
            });
          }

          const base64Audio = message.serverContent?.modelTurn?.parts[0]?.inlineData?.data;
          if (base64Audio && outputAudioContext.current) {
            nextStartTime.current = Math.max(nextStartTime.current, outputAudioContext.current.currentTime);
            const buffer = await decodeAudioData(decode(base64Audio), outputAudioContext.current, 24000, 1);
            const source = outputAudioContext.current.createBufferSource();
            source.buffer = buffer;
            source.connect(outputNode);
            source.addEventListener('ended', () => sources.current.delete(source));
            source.start(nextStartTime.current);
            nextStartTime.current += buffer.duration;
            sources.current.add(source);
          }

          if (message.serverContent?.interrupted) {
            sources.current.forEach(s => {
              try { s.stop(); } catch (e) {}
            });
            sources.current.clear();
            nextStartTime.current = 0;
          }
        },
        onerror: () => stopSession(),
        onclose: () => stopSession(),
      });
    } catch (err) {
      console.error("Voice init failed", err);
    }
  };

  const toggleAssistant = () => {
    if (isActive) {
      stopSession();
    } else {
      setIsMinimized(false);
      startSession();
    }
  };

  return (
    <>
      {/* Floating Button */}
      <button 
        onClick={toggleAssistant}
        className={`fixed bottom-8 ${isRtl ? 'left-8' : 'right-8'} w-16 h-16 rounded-full shadow-2xl flex items-center justify-center transition-all z-40 ${isActive ? 'bg-rose-500 animate-pulse' : 'bg-indigo-600 hover:bg-indigo-700'}`}
      >
        {isActive ? <MicOff className="w-8 h-8 text-white" /> : <Mic className="w-8 h-8 text-white" />}
      </button>

      {/* Assistant Panel */}
      {!isMinimized && (
        <div className={`fixed bottom-28 ${isRtl ? 'left-8' : 'right-8'} w-80 bg-white rounded-3xl shadow-2xl border border-slate-200 overflow-hidden z-40 transition-all ${isRtl ? 'text-right' : 'text-left'}`} dir={isRtl ? 'rtl' : 'ltr'}>
          <div className="bg-indigo-600 p-4 text-white flex items-center justify-between">
            <div className={`flex items-center gap-2 ${isRtl ? 'flex-row-reverse' : ''}`}>
              <div className="w-2 h-2 rounded-full bg-emerald-400 animate-ping" />
              <span className="font-bold text-sm">{t.title}</span>
            </div>
            <button onClick={() => setIsMinimized(true)} className="p-1 hover:bg-indigo-500 rounded-lg">
              <X className="w-4 h-4" />
            </button>
          </div>

          <div className="p-6 h-64 overflow-y-auto space-y-4 bg-slate-50">
            {transcript.length === 0 && !currentThought && (
              <div className="text-center py-8">
                <MessageCircle className="w-12 h-12 text-indigo-100 mx-auto mb-2" />
                <p className="text-xs text-slate-400">{t.help}</p>
              </div>
            )}
            {transcript.map((t, i) => (
              <div key={i} className="bg-white p-3 rounded-2xl text-xs text-slate-700 shadow-sm border border-slate-100">
                {t}
              </div>
