      ${langConstraint}
      All text values in the JSON output MUST be written in the target language.

      Maintain a professional business advisory tone.
    `,
    config: {
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.ARRAY,
        items: {
          type: Type.OBJECT,
          properties: {
            keyInsight: { type: Type.STRING },
            rootCause: { type: Type.STRING },
            riskLevel: { type: Type.STRING, enum: ["Low", "Medium", "High"] },
            recommendedAction: { type: Type.STRING },
            expectedImpact: { type: Type.STRING }
          },
          required: ["keyInsight", "rootCause", "riskLevel", "recommendedAction", "expectedImpact"]
        }
      }
    }
  });

  try {
    const text = response.text?.trim() || "[]";
    return JSON.parse(text);
  } catch (e) {
    console.error("Failed to parse AI response", e);
    return [];
  }
};

const dashboardFunctions: FunctionDeclaration[] = [
  {
    name: 'update_dashboard_filters',
    description: 'Filter the sales dashboard by region, product, distributor, or customer to focus the analysis.',
    parameters: {
      type: Type.OBJECT,
      properties: {
        region: { type: Type.STRING, description: 'The geographic region to filter by (e.g., North, South, East, West)' },
        product: { type: Type.STRING, description: 'Specific product name to analyze' },
        distributor: { type: Type.STRING, description: 'Specific distributor name' },
        customer: { type: Type.STRING, description: 'Specific customer name' },
      }
    }
  },
  {
    name: 'highlight_metric',
    description: 'Direct the users attention to a specific KPI on the dashboard.',
    parameters: {
      type: Type.OBJECT,
      properties: {
        metric: { 
          type: Type.STRING, 
          enum: ['revenue', 'profit', 'outstanding', 'discount'],
          description: 'The KPI metric to highlight' 
        }
      },
      required: ['metric']
    }
  },
  {
    name: 'reset_dashboard',
    description: 'Clear all filters and highlights to show the global view.',
    parameters: { type: Type.OBJECT, properties: {} }
  }
];

export const getVoiceSession = async (
  language: string,
  dataContext: string,
  callbacks: any
) => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
  const langConstraint = language === Language.AUTO 
    ? "You are a multilingual sales advisor. Automatically detect the user's language (English, Urdu, Arabic, Spanish, etc.) and respond in that language. Use RTL orientation for Urdu and Arabic speech."
    : `Communicate exclusively in ${language}.`;

  return ai.live.connect({
    model: 'gemini-2.5-flash-native-audio-preview-12-2025',
    callbacks,
    config: {
      responseModalities: [Modality.AUDIO],
      inputAudioTranscription: {},
      outputAudioTranscription: {},
      tools: [{ functionDeclarations: dashboardFunctions }],
      speechConfig: {
        voiceConfig: { prebuiltVoiceConfig: { voiceName: 'Kore' } },
      },
      systemInstruction: `
        You are an expert Sales Strategy Advisor for an SME. 
        Data Context: ${dataContext}.

        ${langConstraint}

        DYNAMIC DASHBOARD CAPABILITY:
        You can control the user's dashboard using functions. 
        - If they ask about a region, call 'update_dashboard_filters' with that region.
        - If they ask "What is my total debt?", call 'highlight_metric' with 'outstanding'.
        - Use these tools proactively to make your verbal recommendations visual.

        Tone: Professional, decision-focused, and concise.
      `,
    },
  });
};

