interface DashboardProps {
  data: SalesRecord[];
  language: Language;
  highlightedMetric?: string;
}

const UI_TRANSLATIONS: Record<string, any> = {
  [Language.ENGLISH]: {
    rootCause: "Root Cause", recommendation: "Recommendation", expectedImpact: "Expected Impact",
