import React, { useState, useRef, useCallback } from 'react';
import { getVoiceSession } from '../services/gemini';
import { Mic, MicOff, X, MessageCircle } from 'lucide-react';
import { LiveServerMessage, Blob } from '@google/genai';
import { Language, DashboardState } from '../types';

interface VoiceAssistantProps {
  language: string;
  dataContext: string;
  onUpdateDashboard: React.Dispatch<React.SetStateAction<DashboardState>>;
}

const VOICE_UI: Record<string, any> = {
  [Language.ENGLISH]: { title: "Voice Advisor", help: "Ask about regions or metrics", listening: "Listening", standby: "Standby" },
  [Language.URDU]: { title: "وائس مشیر", help: "علاقوں یا میٹرکس کے بارے میں پوچھیں", listening: "سن رہا ہے", standby: "تیار ہے" },
  [Language.ARABIC]: { title: "مستشار صوتي", help: "اسأل عن المناطق أو المقاييس", listening: "جاري الاستماع", standby: "في الانتظار" },
  [Language.AUTO]: { title: "Multi-AI Advisor", help: "Talk in any language", listening: "Listening...", standby: "Standby" },
};

const VoiceAssistant: React.FC<VoiceAssistantProps> = ({ language, dataContext, onUpdateDashboard }) => {
  const [isActive, setIsActive] = useState(false);
  const [isMinimized, setIsMinimized] = useState(true);
  const [transcript, setTranscript] = useState<{ text: string, type: 'user' | 'model' }[]>([]);
  const [currentThought, setCurrentThought] = useState("");
  const [currentUserSpeech, setCurrentUserSpeech] = useState("");

  const inputAudioContext = useRef<AudioContext | null>(null);
  const outputAudioContext = useRef<AudioContext | null>(null);
  const sources = useRef<Set<AudioBufferSourceNode>>(new Set());
  const nextStartTime = useRef(0);
  const sessionPromise = useRef<Promise<any> | null>(null);

  const t = VOICE_UI[language] || VOICE_UI[Language.AUTO];
  const isRtl = language === Language.ARABIC || language === Language.URDU;

  const decode = (base64: string) => {
    const binaryString = atob(base64);
    const len = binaryString.length;
    const bytes = new Uint8Array(len);
    for (let i = 0; i < len; i++) bytes[i] = binaryString.charCodeAt(i);
    return bytes;
  };

  const encode = (bytes: Uint8Array) => {
    let binary = '';
    const len = bytes.byteLength;
    for (let i = 0; i < len; i++) binary += String.fromCharCode(bytes[i]);
    return btoa(binary);
  };

  const decodeAudioData = async (data: Uint8Array, ctx: AudioContext, sampleRate: number, numChannels: number): Promise<AudioBuffer> => {
    const dataInt16 = new Int16Array(data.buffer);
    const frameCount = dataInt16.length / numChannels;
    const buffer = ctx.createBuffer(numChannels, frameCount, sampleRate);
    for (let channel = 0; channel < numChannels; channel++) {
      const channelData = buffer.getChannelData(channel);
      for (let i = 0; i < frameCount; i++) channelData[i] = dataInt16[i * numChannels + channel] / 32768.0;
    }
    return buffer;
  };

  const createBlob = (data: Float32Array): Blob => {
    const l = data.length;
    const int16 = new Int16Array(l);
    for (let i = 0; i < l; i++) int16[i] = data[i] * 32768;
    return { data: encode(new Uint8Array(int16.buffer)), mimeType: 'audio/pcm;rate=16000' };
  };

  const stopSession = useCallback(() => {
    setIsActive(false);
    if (inputAudioContext.current) inputAudioContext.current.close();
    if (outputAudioContext.current) outputAudioContext.current.close();
    sources.current.forEach(s => { try { s.stop(); } catch (e) {} });
    sources.current.clear();
    setCurrentThought("");
    setCurrentUserSpeech("");
  }, []);

  const startSession = async () => {
    try {
      const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
      inputAudioContext.current = new AudioContext({ sampleRate: 16000 });
      outputAudioContext.current = new AudioContext({ sampleRate: 24000 });
      const outputNode = outputAudioContext.current.createGain();
      outputNode.connect(outputAudioContext.current.destination);

      sessionPromise.current = getVoiceSession(language, dataContext, {
        onopen: () => {
          setIsActive(true);
          const source = inputAudioContext.current!.createMediaStreamSource(stream);
          const scriptProcessor = inputAudioContext.current!.createScriptProcessor(4096, 1, 1);
          scriptProcessor.onaudioprocess = (e) => {
            const inputData = e.inputBuffer.getChannelData(0);
            sessionPromise.current?.then((session) => session.sendRealtimeInput({ media: createBlob(inputData) }));
          };
          source.connect(scriptProcessor);
          scriptProcessor.connect(inputAudioContext.current!.destination);
        },
        onmessage: async (message: LiveServerMessage) => {
          // Handle Dashboard Commands (Function Calling)
          if (message.toolCall) {
            for (const fc of message.toolCall.functionCalls) {
              if (fc.name === 'update_dashboard_filters') {
                onUpdateDashboard(prev => ({ 
                  ...prev, 
                  filter: { 
                    region: fc.args.region as string, 
                    product: fc.args.product as string,
                    distributor: fc.args.distributor as string,
                    customer: fc.args.customer as string
                  } 
                }));
              } else if (fc.name === 'highlight_metric') {
                onUpdateDashboard(prev => ({ ...prev, highlightedMetric: fc.args.metric as any }));
                setTimeout(() => onUpdateDashboard(prev => ({ ...prev, highlightedMetric: undefined })), 5000);
              } else if (fc.name === 'reset_dashboard') {
                onUpdateDashboard({ filter: {}, highlightedMetric: undefined });
              }

              // Respond to model to acknowledge execution
              sessionPromise.current?.then(s => s.sendToolResponse({
                functionResponses: [{ id: fc.id, name: fc.name, response: { result: "ok" } }]
              }));
            }
          }

          if (message.serverContent?.outputTranscription) setCurrentThought(prev => prev + message.serverContent!.outputTranscription!.text);
          else if (message.serverContent?.inputTranscription) setCurrentUserSpeech(prev => prev + message.serverContent!.inputTranscription!.text);

          if (message.serverContent?.turnComplete) {
            if (currentUserSpeech) setTranscript(prev => [...prev.slice(-10), { text: currentUserSpeech, type: 'user' }]);
            if (currentThought) setTranscript(prev => [...prev.slice(-10), { text: currentThought, type: 'model' }]);
            setCurrentUserSpeech("");
            setCurrentThought("");
          }

          const base64Audio = message.serverContent?.modelTurn?.parts[0]?.inlineData?.data;
          if (base64Audio && outputAudioContext.current) {
            nextStartTime.current = Math.max(nextStartTime.current, outputAudioContext.current.currentTime);
            const buffer = await decodeAudioData(decode(base64Audio), outputAudioContext.current, 24000, 1);
            const source = outputAudioContext.current.createBufferSource();
            source.buffer = buffer;
            source.connect(outputNode);
            source.start(nextStartTime.current);
            nextStartTime.current += buffer.duration;
            sources.current.add(source);
          }

          if (message.serverContent?.interrupted) {
            sources.current.forEach(s => { try { s.stop(); } catch (e) {} });
            sources.current.clear();
            nextStartTime.current = 0;
            setCurrentThought("");
            setCurrentUserSpeech("");
          }
        },
        onerror: stopSession,
        onclose: stopSession,
      });
    } catch (err) { console.error("Voice init failed", err); }
  };

  const toggleAssistant = () => isActive ? stopSession() : (setIsMinimized(false), startSession());

  return (
    <>
      {isActive && (currentUserSpeech || currentThought) && (
        <div className="fixed bottom-28 left-1/2 -translate-x-1/2 z-50 w-full max-w-2xl px-4 pointer-events-none">
          <div className="bg-slate-900/90 backdrop-blur-md text-white p-6 rounded-2xl shadow-2xl border border-white/20 text-center animate-in fade-in slide-in-from-bottom-6">
             <p className={`text-xl font-medium ${isRtl ? 'rtl' : 'ltr'}`} dir={isRtl ? 'rtl' : 'ltr'}>{currentUserSpeech || currentThought}</p>
             <div className="mt-2 text-[10px] uppercase font-black text-indigo-400 tracking-widest">{currentUserSpeech ? 'User Input' : 'Advisor Voice'}</div>
          </div>
        </div>
      )}

      <button onClick={toggleAssistant} className={`fixed bottom-8 ${isRtl ? 'left-8' : 'right-8'} w-16 h-16 rounded-full shadow-2xl flex items-center justify-center transition-all z-40 ${isActive ? 'bg-rose-500 animate-pulse' : 'bg-indigo-600 hover:bg-indigo-700'}`}>
        {isActive ? <MicOff className="w-8 h-8 text-white" /> : <Mic className="w-8 h-8 text-white" />}
      </button>

      {!isMinimized && (
        <div className={`fixed bottom-28 ${isRtl ? 'left-8' : 'right-8'} w-80 bg-white rounded-3xl shadow-2xl border border-slate-200 overflow-hidden z-40 flex flex-col ${isRtl ? 'text-right' : 'text-left'}`} dir={isRtl ? 'rtl' : 'ltr'}>
          <div className="bg-indigo-600 p-4 text-white flex items-center justify-between shrink-0">
            <div className={`flex items-center gap-2 ${isRtl ? 'flex-row-reverse' : ''}`}>
              <div className="w-2 h-2 rounded-full bg-emerald-400 animate-pulse" />
              <span className="font-bold text-sm">{t.title}</span>
            </div>
            <button onClick={() => setIsMinimized(true)} className="p-1 hover:bg-indigo-500 rounded-lg"><X className="w-4 h-4" /></button>
          </div>
          <div className="flex-1 min-h-[300px] p-4 overflow-y-auto space-y-4 bg-slate-50">
            {transcript.map((item, i) => (
              <div key={i} className={`flex ${item.type === 'user' ? 'justify-end' : 'justify-start'}`}>
                <div className={`max-w-[85%] p-3 rounded-2xl text-xs shadow-sm border ${item.type === 'user' ? 'bg-indigo-600 text-white' : 'bg-white text-slate-700'}`}>{item.text}</div>
              </div>
            ))}
            {(currentUserSpeech || currentThought) && (
              <div className={`flex ${currentUserSpeech ? 'justify-end' : 'justify-start'}`}>
                <div className="max-w-[85%] p-3 rounded-2xl text-xs bg-indigo-50 text-indigo-700 border border-indigo-200 italic animate-pulse">{currentUserSpeech || currentThought}</div>
              </div>
            )}
          </div>
        </div>
      )}
    </>
  );
};

export default VoiceAssistant;

import { GoogleGenAI, Type, Modality, FunctionDeclaration } from "@google/genai";
import { SalesRecord, AdvisoryOutput, RiskLevel, Language } from "../types";

export const analyzeSalesData = async (data: SalesRecord[], prompt: string, language: Language): Promise<AdvisoryOutput[]> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  const summary = data.slice(0, 100).map(r => ({
    r: r.revenue,
    p: r.product,
    c: r.customerName,
    d: r.discount,
    reg: r.region,
    o: r.outstandingAmount
  }));

  const langConstraint = language === Language.AUTO 
    ? "Automatically detect the user's language and respond in kind. Use the appropriate script (LTR/RTL)."
    : `The user's preferred language is ${language}. Respond in ${language}.`;

  const response = await ai.models.generateContent({
    model: "gemini-3-pro-preview",
    contents: `
      Analyze this sales data summary: ${JSON.stringify(summary)}.
      Task: ${prompt}

      CRITICAL REQUIREMENT: 
      ${langConstraint}
      All text values in the JSON output MUST be written in the target language.

      Maintain a professional business advisory tone.
    `,
    config: {
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.ARRAY,
        items: {
          type: Type.OBJECT,
          properties: {
            keyInsight: { type: Type.STRING },
            rootCause: { type: Type.STRING },
            riskLevel: { type: Type.STRING, enum: ["Low", "Medium", "High"] },
            recommendedAction: { type: Type.STRING },
            expectedImpact: { type: Type.STRING }
          },
          required: ["keyInsight", "rootCause", "riskLevel", "recommendedAction", "expectedImpact"]
        }
      }
    }
  });

  try {
    const text = response.text?.trim() || "[]";
    return JSON.parse(text);
  } catch (e) {
    console.error("Failed to parse AI response", e);
    return [];
  }
};

