export const getVoiceSession = async (
  language: string,
  dataContext: string,
  callbacks: any
) => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
  const langConstraint = language === Language.AUTO 
    ? "You are a multilingual sales advisor. Automatically detect the user's language (English, Urdu, Arabic, Spanish, etc.) and respond in that language. Use RTL orientation for Urdu and Arabic speech."
    : `Communicate exclusively in ${language}.`;

  return ai.live.connect({
    model: 'gemini-2.5-flash-native-audio-preview-12-2025',
    callbacks,
    config: {
      responseModalities: [Modality.AUDIO],
      inputAudioTranscription: {},
      outputAudioTranscription: {},
      tools: [{ functionDeclarations: dashboardFunctions }],
      speechConfig: {
        voiceConfig: { prebuiltVoiceConfig: { voiceName: 'Kore' } },
      },
      systemInstruction: `
        You are an expert Sales Strategy Advisor. 
        Data Context: ${dataContext}.

        ${langConstraint}

        DYNAMIC DASHBOARD CAPABILITY:
        You can control the user's dashboard using functions. 
        - If they ask about a region, call 'update_dashboard_filters' with that region.
        - If they ask "What is my total debt?", call 'highlight_metric' with 'outstanding'.
        - Use these tools proactively to make your verbal recommendations visual.

        Tone: Professional, decision-focused, and concise.
      `,
    },
  });
};

